import * as T from './vendor/three.module.js';
export const isLuggage=p=>p?.type==='luggage'&&p.luggageProfile?.reviewed===true;
function outline(w,h,r){const s=new T.Shape(),x=-w/2,y=-h/2;s.moveTo(x+r,y);s.lineTo(x+w-r,y);s.quadraticCurveTo(x+w,y,x+w,y+r);s.lineTo(x+w,y+h-r);s.quadraticCurveTo(x+w,y+h,x+w-r,y+h);s.lineTo(x+r,y+h);s.quadraticCurveTo(x,y+h,x,y+h-r);s.lineTo(x,y+r);s.quadraticCurveTo(x,y,x+r,y);return s;}
// Original closed aluminium case. Overall proportions use the earlier reference; details are adapted.
export function createLuggage(p){const a=p.luggageProfile,W=a.widthCM,H=a.heightCM,D=a.depthCM,g=new T.Group(),steel=new T.MeshStandardMaterial({color:'#b6bcbb',metalness:.67,roughness:.38}),trim=new T.MeshStandardMaterial({color:'#c4c8c1',metalness:.7,roughness:.3}),dark=new T.MeshStandardMaterial({color:'#323f40',roughness:.8}),rubber=new T.MeshStandardMaterial({color:'#252d2b',roughness:.95}),bodyH=H-9,bodyY=5.5+bodyH/2,bevel=1.1,parts=[];
 const add=(geo,mat,x,y,z,role)=>{const o=new T.Mesh(geo,mat);o.position.set(x,y,z);o.userData.role=role;o.castShadow=o.receiveShadow=true;g.add(o);parts.push(role);return o;},box=(x,y,z,w,h,d,m,role)=>add(new T.BoxGeometry(w,h,d),m,x,y,z,role);
 add(new T.ExtrudeGeometry(outline(W-bevel*2,bodyH-bevel*2,3),{depth:D-1-bevel*2,bevelEnabled:true,bevelThickness:bevel,bevelSize:bevel,bevelSegments:3,curveSegments:12}),steel,0,bodyY,-(D-1-bevel*2)/2,'rounded-aluminium-shell');
 for(const side of[-1,1]){for(let i=-5;i<=5;i++)box(i*(W-10)/10,bodyY,side*(D/2-.25),.65,bodyH-9,.5,trim,'vertical-rib');for(const x of[-W/2+3,W/2-3])for(const y of[8,H-6.5]){box(x,y,side*(D/2-.25),5,3,.5,trim,'corner-cap');const rivet=add(new T.CylinderGeometry(.35,.35,.15,10),dark,x,y,side*(D/2-.14),'rivet');rivet.rotation.x=Math.PI/2;}}
 // Four caster assemblies, each with two separately visible wheels and hubs.
 for(const x of[-W/2+5,W/2-5])for(const z of[-D/2+3.2,D/2-3.2]){box(x,5,z,3.4,3,4,dark,'caster-fork');for(const sign of[-1,1]){const wheel=add(new T.CylinderGeometry(2.75,2.75,1.6,20),rubber,x+sign*.9,2.75,z,'caster-wheel');wheel.rotation.z=Math.PI/2;const hub=add(new T.CylinderGeometry(1,1,1.64,16),trim,x+sign*.9,2.75,z,'wheel-hub');hub.rotation.z=Math.PI/2;}}
 for(const x of[-7,7])box(x,H-2.4,0,2,2.2,4,trim,'top-handle-mount');box(0,H-.9,0,15.6,1.8,3,dark,'folded-grab-handle');for(const x of[-6,6])box(x,H-4,3,1.1,1.6,2,trim,'collapsed-pull-rail');box(0,H-4.2,3,13,1,2,dark,'collapsed-pull-handle');
 box(W/2-.5,bodyY,0,1,13,3,dark,'folded-side-grip');for(const y of[bodyY-12,bodyY+12]){box(-W/2+.55,y,0,1.1,5,5,trim,'plain-frame-latch');box(-W/2+.05,y,0,.1,2,2,dark,'illustrative-lock');}for(const sign of[-1,1])box(sign*(W/2-.15),bodyY,0,.3,bodyH-.4,.4,dark,'frame-seam');for(const y of[5.65,H-3.65])box(0,y,0,W-.4,.3,.4,dark,'frame-seam');
 // Merge private geometry by material so a stocked gallery stays bounded in draw calls.
 g.updateMatrixWorld(true);const batches=new Map();for(const o of[...g.children]){const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(o.matrixWorld);let b=batches.get(o.material);if(!b)batches.set(o.material,b={position:[],normal:[]});for(const key of['position','normal'])b[key].push(...geo.attributes[key].array);geo.dispose();o.geometry.dispose();g.remove(o);}for(const[mat,b]of batches){const geo=new T.BufferGeometry();for(const key of['position','normal'])geo.setAttribute(key,new T.Float32BufferAttribute(b[key],3));const o=new T.Mesh(geo,mat);o.castShadow=o.receiveShadow=true;g.add(o);}
 const b=new T.Box3().setFromObject(g),size=b.getSize(new T.Vector3());g.userData={productId:p.id,source:p.source,style:'aluminium-cabin',size:{x:size.x,y:size.y,z:size.z},overallCM:{height:H,width:W,depth:D},handleY:H,parts,volumetric:true,adaptedProportions:true,unlettered:true,closedCase:true};return g;}
export function updateLuggage(w,pose){if(!w.prop||!pose)return;const v=w.luggageScratch??=new T.Vector3();w.player.updateMatrixWorld(true);w.player.userData.limbs[1].userData.grip.getWorldPosition(v);w.player.worldToLocal(v);w.prop.position.copy(v);w.prop.position.y-=w.prop.userData.handleY*.35;w.prop.rotation.set(0,pose.turn,0);w.prop.visible=pose.visible;}
